int main() {
    int taskNum;
    int relationNum;
    cin >> taskNum;
    cin >> relationNum;
    // 构建依赖关系
    map<int, vector<int>> relationMp;
    for (int i = 0; i < relationNum; i++) {
        int a, b;
        cin >> a >> b;
        relationMp[b].push_back(a);
    }
    int res = 1;
    // 定义缓存 防止重复递归
    vector<int> visited(taskNum, INT_MAX);
    for (int i = 0; i < taskNum; i++) {
        int time = DFS(relationMp, i, visited);
        res = max(time, res);
    }
    cout << res;
    return 0;
