package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// DFS求最长深度
func DFS(relationMp map[int][]int, current int, visited []int) int {
    // 已经访问过了，利用缓存
    if visited[current] != 1<<31-1 {
        return visited[current]
    }
​
    res := 0
    relys := relationMp[current]
    // 递归找到最长依赖链
    for _, rely := range relys {
        time := DFS(relationMp, rely, visited)
        if time > res {
            res = time
        }
    }
    visited[current] = res + 1
    return res + 1
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    var taskNum, relationNum int
    fmt.Scanf("%d\n", &taskNum)
    fmt.Scanf("%d\n", &relationNum)
​
    relationMp := make(map[int][]int)
    for i := 0; i < relationNum; i++ {
        line, _ := reader.ReadString('\n')
        parts := strings.Fields(line)
        a, _ := strconv.Atoi(parts[0])
        b, _ := strconv.Atoi(parts[1])
        relationMp[b] = append(relationMp[b], a)
    }
​
    res := 1
    // 定义缓存 防止重复递归
    visited := make([]int, taskNum)
    for i := 0; i < taskNum; i++ {
        visited[i] = 1<<31 - 1
    }
​
    for i := 0; i < taskNum; i++ {
        time := DFS(relationMp, i, visited)
        if time > res {
            res = time
        }
    }
​
    fmt.Println(res)
}
